## Binary meta-regression: mixed vs non-mixed source


::: {#tbl-infection-source-metareg .cell tbl-cap='Meta-regression coefficient for mixed vs non-mixed infection source. A negative Δ log-OR would indicate the short-TTP harm signal is attenuated in studies restricted to a single infection source.'}

```{.r .cell-code .hidden}
#| label: tbl-infection-source-metareg
#| tbl-cap: "Meta-regression coefficient for mixed vs non-mixed infection source. A negative Δ log-OR would indicate the short-TTP harm signal is attenuated in studies restricted to a single infection source."

es_src_bin <- es_mort |>
  filter(!is.na(infection_source), infection_source != "unknown") |>
  mutate(is_mixed = factor(if_else(infection_source == "mixed",
                                   "mixed", "non-mixed"),
                           levels = c("non-mixed", "mixed")))

if (n_distinct(es_src_bin$is_mixed) == 2 && nrow(es_src_bin) >= 8) {
  fit_src_bin <- brm(
    bf(yi | se(sei) ~ 1 + is_mixed + (1 | study_id)),
    data    = es_src_bin,
    prior   = c(prior(normal(0, 1),   class = "Intercept"),
                prior(cauchy(0, 0.5), class = "sd"),
                prior(normal(0, 0.5), class = "b")),
    chains = 4, iter = 4000, warmup = 1000, cores = 4,
    control = list(adapt_delta = 0.99),
    file    = "_brms_cache/primary/fit_src_binary",
    file_refit = "on_change",
    silent = 2, refresh = 0
  )

  d <- as_draws_df(fit_src_bin)
  b <- d$b_is_mixedmixed

  tibble(
    Contrast    = "Mixed vs non-mixed infection source",
    `Δ log-OR`  = sprintf("%+.3f", median(b)),
    `95% CrI`   = sprintf("[%+.3f, %+.3f]", quantile(b, 0.025), quantile(b, 0.975)),
    `P(Δ > 0)`  = sprintf("%.0f%%", mean(b > 0) * 100)
  ) |> gt()
} else {
  cat("Insufficient data for binary meta-regression after excluding unknowns.")
}
```

